hooks.command:
jq -r '.tool_input.file_path // empty' 2>/dev/null | { read -r f; case "$f" in *kanban.md) MISSING=$(grep -E '^\s*-\s+[^[]' "$f" 2>/dev/null | grep -v '\[x\]\|\[-\]\|^#' | grep -v '\[20[0-9][0-9]-' | head -3); if [ -n "$MISSING" ]; then printf '{"systemMessage":"[DS format warning] kanban.md — these cards are missing a [YYYY-MM-DD] session tag (DS write rule):
%s"}
' "$MISSING"; else printf '{"systemMessage":"[DS] kanban.md written — format OK, viewer updated."}
'; fi;; *node-map.md) MISSING=$(grep -E '^\s+-\s+' "$f" 2>/dev/null | grep -v '##\|:' | head -3); if [ -n "$MISSING" ]; then printf '{"systemMessage":"[DS format warning] node-map.md — these lines are missing type: prefix (DS write rule):
%s"}
' "$MISSING"; else printf '{"systemMessage":"[DS] node-map.md written — format OK, viewer updated."}
'; fi;; esac; } 2>/dev/null || true
